import{_ as e,o as l,c as s,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"4. 主干纵贯: CPU/内存 → OS/Linux → 网络/Web → DB → 编译 → 分布式 → AI 的承接链","description":"","frontmatter":{},"headers":[],"relativePath":"prologue/standing-on-shoulders.md","filePath":"prologue/standing-on-shoulders.md","lastUpdated":1788475713000}'),t={name:"prologue/standing-on-shoulders.md"};function i(o,a,r,p,h,c){return l(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="_4-主干纵贯-cpu-内存-→-os-linux-→-网络-web-→-db-→-编译-→-分布式-→-ai-的承接链" tabindex="-1">4. 主干纵贯: CPU/内存 → OS/Linux → 网络/Web → DB → 编译 → 分布式 → AI 的承接链 <a class="header-anchor" href="#_4-主干纵贯-cpu-内存-→-os-linux-→-网络-web-→-db-→-编译-→-分布式-→-ai-的承接链" aria-label="Permalink to &quot;4. 主干纵贯: CPU/内存 → OS/Linux → 网络/Web → DB → 编译 → 分布式 → AI 的承接链&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>前面 <a href="./history">history</a> 讲时间线、<a href="./abstraction-layers">abstraction-layers</a> 讲层级、<a href="./mainframe-xpu">mainframe-xpu</a> 讲形态. 这一节反过来 — <strong>沿&quot;承接链&quot;反向</strong>回到纵贯主线: 每条技术都因&quot;上层拿它做啥&quot;才有意义, 每条新技术大概率是对上层需求的回响.</p><p><strong>承接链</strong> (dependency-of-statements):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物理 → 晶体管 → 数字 → ISA → 微架构 → 内存 → OS → 进程 / 虚存</span></span>
<span class="line"><span>                                            ↓</span></span>
<span class="line"><span>          → 文件系统 → 网络 → Web → 数据库 → 应用 → 业务</span></span>
<span class="line"><span>                  ↘</span></span>
<span class="line"><span>                   → 编译器 → 高级语言 → 框架</span></span>
<span class="line"><span>                                              ↘</span></span>
<span class="line"><span>                                               → 分布式 → 共识 → 一致性 → 云</span></span>
<span class="line"><span>                                                                   ↓</span></span>
<span class="line"><span>                                                                   → AI 训练 → 推理</span></span></code></pre></div><p>每一节都讲: <strong>它的上一站契约是什么 / 它对下一站提供什么 / 没有它上一步走不动</strong>.</p><p>读完应能: 把任意一份你做过 / 你读过的工程问题挂到这条承接链某节点上, 知道&quot;上一站是怎么影响它&quot;和&quot;它对下一站指挥谁&quot;.</p><hr><h2 id="一、cpu-与内存-1945-年那纸契约的开始" tabindex="-1">一、CPU 与内存: 1945 年那纸契约的开始 <a class="header-anchor" href="#一、cpu-与内存-1945-年那纸契约的开始" aria-label="Permalink to &quot;一、CPU 与内存: 1945 年那纸契约的开始&quot;">​</a></h2><h3 id="_1-1-von-neumann-架构" tabindex="-1">1.1 von Neumann 架构 <a class="header-anchor" href="#_1-1-von-neumann-架构" aria-label="Permalink to &quot;1.1 von Neumann 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     CPU  ←─── shared bus ───  Memory</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                 IO</span></span></code></pre></div><p>存储程序 + 共享总线 + 取指 → 解码 → 执行 → 写回. 这套循环在一台机器上仍是 2026 主流 (除 Harvard / NUMA / DSP variant).</p><h3 id="_1-2-第一道承接-性能-vs-内存之间的-frequency-gap" tabindex="-1">1.2 第一道承接: 性能 vs 内存之间的-frequency gap <a class="header-anchor" href="#_1-2-第一道承接-性能-vs-内存之间的-frequency-gap" aria-label="Permalink to &quot;1.2 第一道承接: 性能 vs 内存之间的-frequency gap&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1980  CPU 5MHz, DRAM 100ns     到 CPU 一致</span></span>
<span class="line"><span>1995  CPU 100MHz, DRAM 60ns   缓慢拉开</span></span>
<span class="line"><span>2000  CPU 1GHz, DRAM 6ns       10x 差距</span></span>
<span class="line"><span>2010  CPU 3GHz, DRAM 0.3ns    100x 差距 ← cache 不可缺</span></span>
<span class="line"><span>2026  CPU 5GHz, HBM 0.2ns     memory wall; cache + HBM + CXL</span></span></code></pre></div><p>→ 这就是为什么 <a href="./../computer-arch/memory-hierarchy">第八部分 memory-hierarchy</a> / TLB / DRAM / HBM 全是必需. <strong>内存是 CPU 的最薄弱点, 没有第二选项</strong>, 没有它后整个 OS / 编译 / AI 承接链都得重.</p><h3 id="_1-3-为何-os-出现-单机内部多任务化的契约" tabindex="-1">1.3 为何 OS 出现: 单机内部多任务化的契约 <a class="header-anchor" href="#_1-3-为何-os-出现-单机内部多任务化的契约" aria-label="Permalink to &quot;1.3 为何 OS 出现: 单机内部多任务化的契约&quot;">​</a></h3><ul><li>主机仍单 CPU 时, OS 把&quot;硬件时序&quot;封成&quot;时序进程&quot;; 进程 / 线程 / 上下文切换 = 虚拟时间 + 虚空间.</li><li>一旦有保护模式 + 虚拟内存 + 系统态分, 用户程序不必对每个硬件细节了如指掌 — 这是 OS 出现的核心动因.</li></ul><hr><h2 id="二、os-linux-让程序员不再写硬件" tabindex="-1">二、OS/Linux: 让程序员不再写硬件 <a class="header-anchor" href="#二、os-linux-让程序员不再写硬件" aria-label="Permalink to &quot;二、OS/Linux: 让程序员不再写硬件&quot;">​</a></h2><h3 id="_2-1-进程-虚拟内存-抽象母机" tabindex="-1">2.1 进程 + 虚拟内存 = 抽象母机 <a class="header-anchor" href="#_2-1-进程-虚拟内存-抽象母机" aria-label="Permalink to &quot;2.1 进程 + 虚拟内存 = 抽象母机&quot;">​</a></h3><ul><li>进程 = 一份拥有独立虚地址空间的执行单位; 内核为每个建 page table, 给&quot;独立空间&quot;幻觉.</li><li>调度器 (Linux CFS / EDF / RT) 将 CPU 时间切片让多进程并发&quot;幻觉&quot;.</li><li>上下文切换挂上下文 + TLB; 延迟 ~ 1-10us (见 <a href="./../os/sched/">os/sched</a>).</li></ul><h3 id="_2-2-文件系统-让-io-字节流化" tabindex="-1">2.2 文件系统: 让 IO 字节流化 <a class="header-anchor" href="#_2-2-文件系统-让-io-字节流化" aria-label="Permalink to &quot;2.2 文件系统: 让 IO 字节流化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>OS 抽象</th><th>物理对应</th></tr></thead><tbody><tr><td><code>open(path)</code></td><td>inode 解析 + dentry cache</td></tr><tr><td><code>read/write(fd)</code></td><td>page cache + direct IO</td></tr><tr><td><code>mmap(fd)</code></td><td>TLB + page dirty</td></tr><tr><td><code>fsync(fd)</code></td><td>WAL flush + 块设备 cache flush</td></tr><tr><td><code>sendfile(out, in)</code></td><td>zero-copy, DMA</td></tr></tbody></table><p>→ 见 <a href="./../os/fs/">os/fs</a>.</p><h3 id="_2-3-网络栈与-epoll-io-uring" tabindex="-1">2.3 网络栈与 epoll/io_uring <a class="header-anchor" href="#_2-3-网络栈与-epoll-io-uring" aria-label="Permalink to &quot;2.3 网络栈与 epoll/io_uring&quot;">​</a></h3><ul><li><code>socket()</code> 复用 fd 抽象; TCP 4 层 + IP + 驱动.</li><li>C10K 问题 (2002): 单机 10000 连接压力 → epoll (2002) + kqueue; 后 100K / 1M 由 io_uring (2019) 实现.</li></ul><h3 id="_2-4-同步原语与内存模型" tabindex="-1">2.4 同步原语与内存模型 <a class="header-anchor" href="#_2-4-同步原语与内存模型" aria-label="Permalink to &quot;2.4 同步原语与内存模型&quot;">​</a></h3><ul><li>进程内 sync: mutex / semaphore / rwlock; kernel 内 futex + CAS; 浪费大批 lock-free / RCU 设计.</li></ul><p>→ 见 <a href="./../os/lock/">os/lock</a>.</p><h3 id="_2-5-os-对承接链-承诺-的清单一句话" tabindex="-1">2.5 OS 对承接链&quot;承诺&quot;的清单一句话 <a class="header-anchor" href="#_2-5-os-对承接链-承诺-的清单一句话" aria-label="Permalink to &quot;2.5 OS 对承接链&quot;承诺&quot;的清单一句话&quot;">​</a></h3><ul><li>进程隔离的虚空间</li><li>通用 IO 的字节流</li><li>跨进程的协议: socket / IPC / pipe</li><li>命名隔离: filesystem</li><li>安全 / 权限: uid / cgroup / capability</li></ul><p>这一组契约就是后续一切软件的&quot;地基&quot;.</p><hr><h2 id="三、网络与-web-让孤立的机器互连" tabindex="-1">三、网络与 Web: 让孤立的机器互连 <a class="header-anchor" href="#三、网络与-web-让孤立的机器互连" aria-label="Permalink to &quot;三、网络与 Web: 让孤立的机器互连&quot;">​</a></h2><h3 id="_3-1-ip-tcp-契约" tabindex="-1">3.1 IP/TCP 契约 <a class="header-anchor" href="#_3-1-ip-tcp-契约" aria-label="Permalink to &quot;3.1 IP/TCP 契约&quot;">​</a></h3><ul><li>IP: 不可靠的、按 packet; 上层自己保序 / 重传可靠性.</li><li>TCP: reliable byte stream; congestion control (Reno/Cubic/BBR); 3-way handshake + 4-way close.</li></ul><h3 id="_3-2-http-tls-最薄一英里" tabindex="-1">3.2 HTTP / TLS: 最薄一英里 <a class="header-anchor" href="#_3-2-http-tls-最薄一英里" aria-label="Permalink to &quot;3.2 HTTP / TLS: 最薄一英里&quot;">​</a></h3><ul><li>HTTP/0.9-1.1 一条 TCP 一个 request; HTTP/2 (2015) 一条连接多路 stream; HTTP/3 over QUIC (2022+) → 见 <a href="./../networking/quic/">networking/quic</a>.</li><li>TLS 1.3 (2018) 1-RTT + 0-RTT; X.509 + PKI + CT.</li></ul><h3 id="_3-3-web-把客户端拉成终端" tabindex="-1">3.3 Web 把客户端拉成终端 <a class="header-anchor" href="#_3-3-web-把客户端拉成终端" aria-label="Permalink to &quot;3.3 Web 把客户端拉成终端&quot;">​</a></h3><ul><li>浏览器是 OS 上的一个 &quot;虚拟机&quot;; HTML/CSS/JS DOM/WASM/WebGPU 成熟.</li><li>2024+ WebGPU 让浏览器可调 GPU 算 + WASI 让 WASM 调本地 file. 浏览器从文档看待器 → 通用客户端 → 实际计算平台.</li></ul><h3 id="_3-4-网络对-db-应用的影响" tabindex="-1">3.4 网络对 DB / 应用的影响 <a class="header-anchor" href="#_3-4-网络对-db-应用的影响" aria-label="Permalink to &quot;3.4 网络对 DB / 应用的影响&quot;">​</a></h3><ul><li>DB 出现 single machine 邦联后就受网络影响; 网络 RTT 决定 commit 时间 → 数据库 replication 的延迟很关键.</li><li>应用从 monolith → SOA → micro-service → service mesh 全由于网络可靠性 / IP/TLS / k8s / 等成熟.</li></ul><hr><h2 id="四、数据库系统-让状态在并发-故障下成立" tabindex="-1">四、数据库系统: 让状态在并发 / 故障下成立 <a class="header-anchor" href="#四、数据库系统-让状态在并发-故障下成立" aria-label="Permalink to &quot;四、数据库系统: 让状态在并发 / 故障下成立&quot;">​</a></h2><h3 id="_4-1-为什么需要-db-而不是文件" tabindex="-1">4.1 为什么需要 DB 而不是文件 <a class="header-anchor" href="#_4-1-为什么需要-db-而不是文件" aria-label="Permalink to &quot;4.1 为什么需要 DB 而不是文件&quot;">​</a></h3><p>OS 文件系统只承诺 &quot;字节流&quot;, 没说&quot;原子写 / 多 client 并发 / crash 后一致&quot;. DB 把这些不变式钉死:</p><ul><li>ACID (事务原子性 / 一致性 / 隔离性 / 持久性).</li><li>MVCC + WAL + 2PL + snapshot isolation.</li><li>主流: PostgreSQL / MySQL (OLTP), ClickHouse / Snowflake (OLAP), Redis / Dynamo (KV).</li></ul><p>→ 见 <a href="./../databases/">databases</a>. 这是承接链 <strong>保存状态</strong> 的核心一层.</p><h3 id="_4-2-数据库如何依赖-os-网络-硬件" tabindex="-1">4.2 数据库如何依赖 OS / 网络 / 硬件 <a class="header-anchor" href="#_4-2-数据库如何依赖-os-网络-硬件" aria-label="Permalink to &quot;4.2 数据库如何依赖 OS / 网络 / 硬件&quot;">​</a></h3><ul><li>依赖文件 + fsync 确保持久性 (write-ahead log); 这是个 OS 与块设备之间的契约. 一旦块设备&quot;写入但未 flush&quot; 破坏这一契约, ACID 就有空洞 (e.g. SSD cache 丢).</li><li>依赖网络做 replication; latency → Paxos / Raft 单写 1 RTT trip.</li><li>依赖 page cache / direct IO / io_uring / NVMe 多队列 → 与 OS / 块设备协同.</li></ul><h3 id="_4-3-db-是-web-后端的-状态核心" tabindex="-1">4.3 DB 是 web 后端的&quot;状态核心&quot; <a class="header-anchor" href="#_4-3-db-是-web-后端的-状态核心" aria-label="Permalink to &quot;4.3 DB 是 web 后端的&quot;状态核心&quot;&quot;">​</a></h3><ul><li>Web 上层把所有&quot;状态&quot;丢 DB, 自己做无状态服务 + 容器; K8s + RDS 模型 一切都这么搭.</li><li>DB 与分布式系统的 cap 线 / 一致性范畴都来自这条承接.</li></ul><hr><h2 id="五、编译器-高级语言-让机器可读变成人可写" tabindex="-1">五、编译器 / 高级语言: 让机器可读变成人可写 <a class="header-anchor" href="#五、编译器-高级语言-让机器可读变成人可写" aria-label="Permalink to &quot;五、编译器 / 高级语言: 让机器可读变成人可写&quot;">​</a></h2><h3 id="_5-1-编译器史的简线" tabindex="-1">5.1 编译器史的简线 <a class="header-anchor" href="#_5-1-编译器史的简线" aria-label="Permalink to &quot;5.1 编译器史的简线&quot;">​</a></h3><ul><li>1957 FORTRAN; 1972 C; 1990 GCC; 2000 LLVM; 2010 V8 Tiered JIT; 2020 Rust + LLVM + Miri.</li><li>编译器把&quot;人工可写&quot;高级语言转到&quot;机器可执行&quot; ISA, 同时做优化: SSA / CFG / constant folding / dead-code / loop unroll / auto-vectorize / IPO.</li><li>见 <a href="./../compilers/">compilers</a>.</li></ul><h3 id="_5-2-编译器承接了-os-加上后程序可点点" tabindex="-1">5.2 编译器承接了&quot;OS 加上后程序可点点&quot; <a class="header-anchor" href="#_5-2-编译器承接了-os-加上后程序可点点" aria-label="Permalink to &quot;5.2 编译器承接了&quot;OS 加上后程序可点点&quot;&quot;">​</a></h3><ul><li>OS 提供 syscall ABI; 编译器知道怎么写出对 ABI 正确的代码 (caller/callee saved regs, stack frame).</li><li>语言层 → 库 → syscall → kernel → driver.</li></ul><h3 id="_5-3-高级语言运行时-抽象-gc-与线程的延展" tabindex="-1">5.3 高级语言运行时: 抽象 GC 与线程的延展 <a class="header-anchor" href="#_5-3-高级语言运行时-抽象-gc-与线程的延展" aria-label="Permalink to &quot;5.3 高级语言运行时: 抽象 GC 与线程的延展&quot;">​</a></h3><ul><li>Java / Python / Go / Rust / JS 等, 加 GC / 协程 / async / await / Future / channel; 都把 OS 线程 + sqlite / pipe 的细节包到运行时.</li></ul><hr><h2 id="六、分布式系统-一台机器不够用后-n-台协同" tabindex="-1">六、分布式系统: 一台机器不够用后 N 台协同 <a class="header-anchor" href="#六、分布式系统-一台机器不够用后-n-台协同" aria-label="Permalink to &quot;六、分布式系统: 一台机器不够用后 N 台协同&quot;">​</a></h2><h3 id="_6-1-必来" tabindex="-1">6.1 必来 <a class="header-anchor" href="#_6-1-必来" aria-label="Permalink to &quot;6.1 必来&quot;">​</a></h3><ul><li>单机扩展到 +10GHz 时 CPU 与内存墙都搅过; 一台机器能跑的 QPS / 数据量 / HA 都不可满足 → 必须多机.</li><li>多机 = 网络 → 延迟 + 故障 + 异构 → 必须协议 (CAP / 一致性).</li><li>Multi-Paxos / Raft / Gossip + CRDT; 见 <a href="./../distributed/">distributed</a>.</li></ul><h3 id="_6-2-共识-状态机复制的工具" tabindex="-1">6.2 共识 = 状态机复制的工具 <a class="header-anchor" href="#_6-2-共识-状态机复制的工具" aria-label="Permalink to &quot;6.2 共识 = 状态机复制的工具&quot;">​</a></h3><ul><li>1990 Lamport Paxos; 2014 Raft.</li><li>任何&quot;被许多机器共享的状态&quot;几乎都用这俩或其变种. -共识是承接链中<strong>调度多机</strong>, 把&quot;不可靠网络 + 部分机器丢&quot;转成&quot;一组虚拟主机机&quot;.</li></ul><h3 id="_6-3-一致性与时间" tabindex="-1">6.3 一致性与时间 <a class="header-anchor" href="#_6-3-一致性与时间" aria-label="Permalink to &quot;6.3 一致性与时间&quot;">​</a></h3><ul><li>物理时钟不可同步全 → logical clock (Lamport, vector clock, HLC) → 全序 / 偏序隔离.</li><li>TrueTime (Spanner) / HLC (CockroachDB) 借 GPS + 原子钟做单亿误差.</li></ul><h3 id="_6-4-把-集群-抽象成-单机" tabindex="-1">6.4 把&quot;集群&quot;抽象成&quot;单机&quot; <a class="header-anchor" href="#_6-4-把-集群-抽象成-单机" aria-label="Permalink to &quot;6.4 把&quot;集群&quot;抽象成&quot;单机&quot;&quot;">​</a></h3><ul><li>K8s 把 10000 台集群抽象成一组 control-plane API; 用户提 YAML 即一份声明式资源 → 内部 reconciliation loop → 自动调拨.</li><li>见 <a href="./../system-design/case/k8s-control-plane">system-design/case/k8s-control-plane</a>.</li></ul><hr><h2 id="七、web-后端-微服务-系统设计" tabindex="-1">七、Web 后端 / 微服务 / 系统设计 <a class="header-anchor" href="#七、web-后端-微服务-系统设计" aria-label="Permalink to &quot;七、Web 后端 / 微服务 / 系统设计&quot;">​</a></h2><h3 id="_7-1-估算-→-缓存-→-队列-→-限流" tabindex="-1">7.1 估算 → 缓存 → 队列 → 限流 <a class="header-anchor" href="#_7-1-估算-→-缓存-→-队列-→-限流" aria-label="Permalink to &quot;7.1 估算 → 缓存 → 队列 → 限流&quot;">​</a></h3><ul><li>Little&#39;s Law + Little&#39;s Law → 平均 response = arrival_time / (1 - rho); back-of-envelope 计算 QPS / IOPS / 带宽 / 存储.</li><li>cache-aside / write-through / write-behind; 失效 (穿透 / 击穿 / 雪崩).</li><li>队列 Kafka / Pulsar / SQS; at-least-once vs exactly-once; outbox pattern.</li></ul><h3 id="_7-2-系统设计-反推与分解" tabindex="-1">7.2 系统设计 = 反推与分解 <a class="header-anchor" href="#_7-2-系统设计-反推与分解" aria-label="Permalink to &quot;7.2 系统设计 = 反推与分解&quot;">​</a></h3><ul><li>任务需求 → 估算 → 主组件 → 数据流 → 失败模式 → 可观测 → 上云.</li><li>见 <a href="./../system-design/">system-design</a>.</li></ul><h3 id="_7-3-微服务网格的承接" tabindex="-1">7.3 微服务网格的承接 <a class="header-anchor" href="#_7-3-微服务网格的承接" aria-label="Permalink to &quot;7.3 微服务网格的承接&quot;">​</a></h3><ul><li>服务网格 (Istio / Linkerd / Envoy) 在 K8s 之上加: mTLS + routing + 重试 / timeout / 熔断 + observability + sidecar proxy.</li></ul><hr><h2 id="八、ai-状态机的-高维-模式化" tabindex="-1">八、AI: 状态机的&quot;高维&quot;模式化 <a class="header-anchor" href="#八、ai-状态机的-高维-模式化" aria-label="Permalink to &quot;八、AI: 状态机的&quot;高维&quot;模式化&quot;">​</a></h2><h3 id="_8-1-它从哪里踏上承接链" tabindex="-1">8.1 它从哪里踏上承接链 <a class="header-anchor" href="#_8-1-它从哪里踏上承接链" aria-label="Permalink to &quot;8.1 它从哪里踏上承接链&quot;">​</a></h3><ul><li><strong>数学</strong> (第零部分): 反向传播 + 链式法则 + softmax / SVD + 概率分布 → 是 AI 训练算法本身.</li><li><strong>硬件</strong> (第八部分): GPU/TPU/NPU 异构芯片 + HBM + 互联 → 性能 + 显存决定 能不能训.</li><li><strong>OS</strong> (第二部分): Linux + cgroup + nccl + RDMA → GPU 集群的互联.</li><li><strong>网络</strong> (第三部分): RoCE v2 / nvBandwidth → 多卡通信快; HTTPS 推理 API.</li><li><strong>数据库</strong> (第四部分): 训练数据集存储; vector database 给 LLM 工具调用 / RAG.</li><li><strong>分布式</strong> (第六部分): model 并行 / data 并行 / pipeline 并行 / ZeRO-3 → 8 卡变 65K 卡.</li><li><strong>系统设计</strong> (第七部分): inference service 设计 / KV cache 共享 / 多 tenant / autoscaling.</li></ul><h3 id="_8-2-ai-反过来反推这条承接链" tabindex="-1">8.2 AI 反过来反推这条承接链 <a class="header-anchor" href="#_8-2-ai-反过来反推这条承接链" aria-label="Permalink to &quot;8.2 AI 反过来反推这条承接链&quot;">​</a></h3><ul><li>GPU/NPU 出来前: CPU 单线喂不饱; 现在 GPU 训练一批 7B 模型 1000 卡密集用; <strong>NCCL + RDMA + GPUDirect-RDMA</strong> 是新协议栈; 这把承接链的工具形态全部改.</li><li>LLM 推理: 把反向 AD 的 cache 改成 KV cache, 不是梯度是 attention 中间结果 → 这反过来推 HBM / CXL / 互联带宽.</li><li>Agent (2025+) 反推 RPC / tool/API 框架: MCP 协议让 LLM 配 SQL / fs / browser 成为可工程交互.</li></ul><h3 id="_8-3-新承接-ai-→-系统-os-的反向输入" tabindex="-1">8.3 新承接: AI → 系统 / OS 的反向输入 <a class="header-anchor" href="#_8-3-新承接-ai-→-系统-os-的反向输入" aria-label="Permalink to &quot;8.3 新承接: AI → 系统 / OS 的反向输入&quot;">​</a></h3><ul><li>GPU 集群调度: Borg/Omega/Kubernetes 都要支持 device plugin + topology-aware; Linux 内核对 GPU 的 cgroup 隔离还很弱 (2024+ 才有 NVIDIA MIG 与 DPDK 隔离成熟).</li><li>ML 监控与 trace: OpenTelemetry 增强 ML metrics; 单步训练几百次需 trace-blame 与 schema.</li><li>推理直接接 OS syscall (e.g. AI tool use) → 安全沙箱新关注.</li></ul><hr><h2 id="九、整个承接链图" tabindex="-1">九、整个承接链图 <a class="header-anchor" href="#九、整个承接链图" aria-label="Permalink to &quot;九、整个承接链图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物理 ─ 晶体管 ─ 数字 ─ ISA ─ microarch</span></span>
<span class="line"><span>                                  ↓</span></span>
<span class="line"><span>                            虚拟内存 + CPU cache</span></span>
<span class="line"><span>                                  ↓</span></span>
<span class="line"><span>            ┌───────── OS (Linux Kernel) ─────┐</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>        File System    网络 (TCP/IP)      进程 + 调度</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>        块设备 / SSD   HTTP / TLS          线程/协程</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>            DB          Web/REST        编译器 / 语言运行时</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>            OLAP / OLTP    LAMP/MEAN/MERN   JIT/HotSpot/V8</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>            分布式: KV / Queue / Consensus / K8s</span></span>
<span class="line"><span>            ↓             ↓                 ↓</span></span>
<span class="line"><span>───────────────────────────────────────────</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                    AI: Training + Inference</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                  GPU / NPU / TPU / 异构 XPU</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                  HBM4 + NVLink + CXL 3.x</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                  Agent + MCP + 推理 SDK</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                  === 下一波新抽象 ===</span></span></code></pre></div><p>每一节点都为前一节点顺承不变式; 跳一节点工程就断了.</p><hr><h2 id="十、五个-如果是新工程师-你正在哪段承接-的练习" tabindex="-1">十、五个&quot;如果是新工程师, 你正在哪段承接&quot;的练习 <a class="header-anchor" href="#十、五个-如果是新工程师-你正在哪段承接-的练习" aria-label="Permalink to &quot;十、五个&quot;如果是新工程师, 你正在哪段承接&quot;的练习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你做的事</th><th>你主要在哪段承接</th></tr></thead><tbody><tr><td>写 Web 后端 + DB RDS</td><td>Web 后端 / DB / OS (epoll+socket)</td></tr><tr><td>写 mobile app</td><td>高级语言运行时 / Android/iOS SDK / NPU</td></tr><tr><td>写 CUDA kernel 训大模型</td><td>物理层之上的 microarch / ISA (PTX) / AI 调度栈</td></tr><tr><td>写 Kubernetes operator</td><td>分布式 / 系统 / OS</td></tr><tr><td>写 Linux 内核 driver</td><td>OS / ISA / 微架构</td></tr></tbody></table><p>→ 这套表帮你定位&quot;读完哪几章本书就可以接入你工作&quot;.</p><hr><h2 id="十一、与第零部分数学的加乘" tabindex="-1">十一、与第零部分数学的加乘 <a class="header-anchor" href="#十一、与第零部分数学的加乘" aria-label="Permalink to &quot;十一、与第零部分数学的加乘&quot;">​</a></h2><p>数学 (第零部分) 不在承接链有自己的节点 — 它<strong>横跨所有节点</strong>:</p><ul><li>第 1-2 物理层 - 信息论/熵与极限.</li><li>ISA 与微架构 - 不必数学.</li><li>OS / 调度 - 概率 + 排队 + 极限.</li><li>网络 - 概率分布 + 信息论熵 / 信道容量.</li><li>DB - 关系代数 + 估计 + 一致性序.</li><li>分布式 - 偏序 + 概率 + 信息论.</li><li>AI - 微积分 + 线代 + 概率 + 优化.</li></ul><p>→ 这就是为什么数学放在第零部分: <strong>每段承接都要用到</strong>, 不能单挑一节点上.</p><hr><h2 id="十二、结束-速查表" tabindex="-1">十二、结束 + 速查表 <a class="header-anchor" href="#十二、结束-速查表" aria-label="Permalink to &quot;十二、结束 + 速查表&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页唤回:</p><ul><li><strong>承接链</strong>: 物理 → ISA → 微架构 → 内存 → OS → 进程 + 文件 + 网络 → 编译器 → DB → 分布式 → AI.</li><li>每一段都需要上段提供契约; 没有它下段最后一段不动.</li><li>OS 给&quot;进程 + 字节流文件 + socket&quot;; 没它再好硬件也只是 DSP.</li><li>DB 提供并发 + 故障下状态一致; ACID = WAL + 2PL + MVCC 等.</li><li>网络把孤立机器拥成集群; CAP / 共识 / 一致性序随之而来.</li><li>分布式抽象集群为虚拟机; K8s + Raft + CRDT 这套套餐现成.</li><li>AI 反过来给承接链压力, 推 GPU/互联/HBM/CXL/MCP.</li><li>数学横跨所有节点 = 第零部分必须放最前.</li></ul></div><hr><p>下一篇: <a href="./map">5. 全书地图: 13 部分与导论的交叉索引</a>.</p>`,104)])])}const b=e(t,[["render",i]]);export{d as __pageData,b as default};
